package com.parvnigam.careerbridge;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.security.oauth2.jwt.JwtEncoder;
import tools.jackson.databind.JsonNode;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:campusdrives;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop","app.upload-dir=target/drive-test-uploads","app.mail-enabled=false","app.local-email-testing=false","app.ai-url=","app.redis-enabled=false"})
class CampusDriveTests {
    @LocalServerPort int port;@Autowired Store r;@Autowired JwtEncoder encoder;
    AcademicReviewTests fixture(){var x=new AcademicReviewTests();x.port=port;x.r=r;x.encoder=encoder;return x;}
    Model.Account seeded(String email){return r.accounts().findByEmail(email).orElseThrow();}
    String jwt(String email){return fixture().token(seeded(email));}
    Long campus(){return seeded("placement@careerbridge.dev").universityId;}
    JsonNode call(String method,String path,String token,Object body,int expected)throws Exception{var f=fixture();var response=f.call(method,path,token,body);assertEquals(expected,response.statusCode(),response.body());return f.tree(response);}
    Long job()throws Exception{var data=new LinkedHashMap<String,Object>();data.putAll(Map.of("title","Campus opening "+UUID.randomUUID(),"description","Fictional Java internship","location","Delhi NCR","employmentType","INTERNSHIP","workMode","HYBRID","requiredSkills",List.of("Java"),"minCgpa",7.0,"deadline",LocalDate.now().plusDays(10).toString()));return call("POST","/recruiter/jobs",jwt("recruiter@careerbridge.dev"),data,201).get("id").asLong();}
    Map<String,Object> input(Long jobId,boolean verification){var m=new LinkedHashMap<String,Object>();Instant now=Instant.now();m.putAll(Map.of("title","Campus event "+UUID.randomUUID(),"jobId",jobId,"universityId",campus(),"venue","Fictional campus hall","instructions","Bring your college ID.","registrationOpensAt",now.minusSeconds(60).toString(),"registrationClosesAt",now.plusSeconds(3600).toString(),"requireVerifiedAcademics",verification,"rounds",List.of(Map.of("name","Assessment","scheduledAt",now.plusSeconds(7200).toString(),"venue","Hall A"),Map.of("name","Interview","scheduledAt",now.plusSeconds(10800).toString(),"venue","Room B"))));return m;}
    JsonNode draft(Long jobId,boolean verified)throws Exception{return call("POST","/placement/drives",jwt("placement@careerbridge.dev"),input(jobId,verified),201);}
    JsonNode status(JsonNode d,String status,int expected)throws Exception{return call("PATCH","/placement/drives/"+d.get("id").asLong()+"/status",jwt("placement@careerbridge.dev"),Map.of("version",d.get("version").asLong(),"status",status),expected);}
    JsonNode published(Long jobId,boolean verified)throws Exception{return status(draft(jobId,verified),"PUBLISHED",200);}
    JsonNode register(Model.Account a,JsonNode d,int expected)throws Exception{return call("POST","/student/drives/"+d.get("id").asLong()+"/registration",fixture().token(a),null,expected);}
    JsonNode detail(JsonNode d,String token)throws Exception{return call("GET","/drives/"+d.get("id").asLong(),token,null,200);}
    void began(JsonNode d){int i=0;for(var round:r.driveRounds().findByDriveIdOrderByPositionAsc(d.get("id").asLong())){round.scheduledAt=Instant.now().minusSeconds(20-(++i)*5);r.driveRounds().save(round);}}
    JsonNode result(JsonNode d,JsonNode result,String attendance,String outcome,String note,int expected)throws Exception{return call("PATCH","/placement/drives/"+d.get("id").asLong()+"/results/"+result.get("id").asLong(),jwt("placement@careerbridge.dev"),Map.of("version",result.get("version").asLong(),"attendance",attendance,"outcome",outcome,"note",note),expected);}

    @Test void publicOpeningsRemainDirectAndDraftsAreHidden()throws Exception{var student=fixture().student();Long job=job();var draft=draft(job,false);assertFalse(call("GET","/drives",fixture().token(student),null,200).toString().contains(draft.get("title").asText()));call("GET","/drives/"+draft.get("id").asLong(),fixture().token(student),null,403);call("GET","/drives/"+draft.get("id").asLong(),jwt("recruiter@careerbridge.dev"),null,403);assertTrue(call("GET","/jobs",fixture().token(student),null,200).toString().contains("Campus opening"));call("POST","/student/applications",fixture().token(student),Map.of("jobId",job),201);var d=status(draft,"PUBLISHED",200);var joined=register(student,d,200);assertEquals(1,r.applications().findByStudentIdOrderByCreatedAtDesc(student.id).size());assertEquals(r.applications().findByStudentIdAndJobId(student.id,job).orElseThrow().id.longValue(),joined.get("registration").get("applicationId").asLong());assertTrue(call("GET","/notifications",fixture().token(student),null,200).toString().contains("registration confirmed"));}
    @Test void differentUniversitiesAndRecruiterOwnershipAreEnforced()throws Exception{Long job=job();var d=published(job,false);var outside=fixture().account(Model.Role.STUDENT,campus()+1);var officer=fixture().account(Model.Role.PLACEMENT_OFFICER,campus()+1);call("GET","/drives/"+d.get("id").asLong(),fixture().token(outside),null,403);register(outside,d,403);call("PATCH","/placement/drives/"+d.get("id").asLong()+"/status",fixture().token(officer),Map.of("version",d.get("version").asLong(),"status","CANCELLED"),403);call("GET","/drives/"+d.get("id").asLong(),jwt("other-recruiter@careerbridge.dev"),null,403);assertEquals(0,call("GET","/drives",fixture().token(officer),null,200).size());call("GET","/drives/"+d.get("id").asLong(),jwt("admin@careerbridge.dev"),null,200);var forged=input(job,false);forged.put("universityId",campus()+1);call("POST","/placement/drives",jwt("placement@careerbridge.dev"),forged,403);var foreignJob=r.jobs().findById(job).orElseThrow();foreignJob.universityId=campus()+1;r.jobs().save(foreignJob);call("POST","/placement/drives",jwt("placement@careerbridge.dev"),input(job,false),400);}
    @Test void driveRegistrationCreatesOneApplicationAndDuplicateIsConflict()throws Exception{var a=fixture().student();Long job=job();var d=published(job,false);var joined=register(a,d,200);assertEquals("REGISTERED",joined.get("registration").get("progress").asText());assertEquals(1,r.applications().findByStudentIdOrderByCreatedAtDesc(a.id).size());assertEquals(2,joined.get("registration").get("results").size());register(a,d,409);var staff=detail(d,jwt("placement@careerbridge.dev"));assertEquals(1,staff.get("participants").size());assertEquals(a.email,staff.get("participants").get(0).get("student").get("email").asText());assertEquals(1,detail(d,jwt("recruiter@careerbridge.dev")).get("participants").size());}
    @Test void currentEligibilityAndOptionalAcademicVerificationAreChecked()throws Exception{var f=fixture();var a=f.student();Long job=job();var d=published(job,true);assertFalse(detail(d,f.token(a)).get("canRegister").asBoolean());register(a,d,400);var proof=f.pending(a,f.documents(a));assertEquals(200,f.review(proof,f.staff(),"VERIFIED","").statusCode());assertTrue(detail(d,f.token(a)).get("canRegister").asBoolean());var profile=r.profiles().findByUserId(a.id).orElseThrow();profile.cgpa=6.0;profile=r.profiles().save(profile);register(a,d,400);profile.cgpa=9.0;profile=r.profiles().save(profile);var changed=f.academicInput();changed.put("activeBacklogs",1);assertEquals(200,f.call("PUT","/student/academics",f.token(a),changed).statusCode());register(a,d,400);assertEquals(0,r.applications().findByStudentIdOrderByCreatedAtDesc(a.id).size());}
    @Test void windowOpeningScopeChangesAndClosedJobsBlockRegistration()throws Exception{var a=fixture().student();Long job=job();var d=published(job,false);var entity=r.drives().findById(d.get("id").asLong()).orElseThrow();entity.registrationOpensAt=Instant.now().plusSeconds(120);entity=r.drives().save(entity);register(a,d,400);entity.registrationOpensAt=Instant.now().minusSeconds(120);entity.registrationClosesAt=Instant.now().minusSeconds(1);entity=r.drives().save(entity);register(a,d,400);entity.registrationClosesAt=Instant.now().plusSeconds(500);entity=r.drives().save(entity);var opening=r.jobs().findById(job).orElseThrow();opening.status="CLOSED";opening=r.jobs().save(opening);register(a,d,400);opening.status="ACTIVE";opening.universityId=campus()+1;opening=r.jobs().save(opening);register(a,d,400);var unavailable=detail(d,fixture().token(a)).get("job");assertEquals("UNAVAILABLE",unavailable.get("status").asText());assertFalse(unavailable.has("description"));}
    @Test void invalidSchedulesDraftEditingAndStatusVersionsAreValidated()throws Exception{Long job=job();var bad=input(job,false);bad.put("registrationClosesAt",Instant.now().minusSeconds(1).toString());call("POST","/placement/drives",jwt("placement@careerbridge.dev"),bad,400);bad=input(job,false);bad.put("rounds",List.of(Map.of("name","Interview","scheduledAt",Instant.now().plusSeconds(10).toString(),"venue","Room")));call("POST","/placement/drives",jwt("placement@careerbridge.dev"),bad,400);var d=draft(job,false);var edited=input(job,false);edited.put("version",d.get("version").asLong());edited.put("title","Updated campus event");d=call("PUT","/placement/drives/"+d.get("id").asLong(),jwt("placement@careerbridge.dev"),edited,200);assertEquals(2,d.get("rounds").size());call("PATCH","/placement/drives/"+d.get("id").asLong()+"/status",jwt("placement@careerbridge.dev"),Map.of("version",999,"status","PUBLISHED"),409);d=status(d,"PUBLISHED",200);edited.put("version",d.get("version").asLong());call("PUT","/placement/drives/"+d.get("id").asLong(),jwt("placement@careerbridge.dev"),edited,409);status(d,"DRAFT",400);status(d,"COMPLETED",409);}
    @Test void withdrawalRetainsApplicationAndAllowsRegistrationAgain()throws Exception{var a=fixture().student();var d=published(job(),false);var joined=register(a,d,200);long application=joined.get("registration").get("applicationId").asLong();var left=call("DELETE","/student/drives/"+d.get("id").asLong()+"/registration",fixture().token(a),null,200);assertEquals("WITHDRAWN",left.get("registration").get("progress").asText());assertEquals(Model.Stage.APPLIED,r.applications().findById(application).orElseThrow().status);joined=register(a,d,200);assertEquals(application,joined.get("registration").get("applicationId").asLong());began(d);call("DELETE","/student/drives/"+d.get("id").asLong()+"/registration",fixture().token(a),null,409);}
    @Test void attendanceSequenceAndFeedbackAreEnforcedWithoutChangingRecruiterStages()throws Exception{var a=fixture().student();var d=published(job(),false);register(a,d,200);var staff=detail(d,jwt("placement@careerbridge.dev"));var results=staff.get("participants").get(0).get("results");result(d,results.get(0),"PRESENT","PASSED","",409);began(d);result(d,results.get(1),"PRESENT","PASSED","",409);result(d,results.get(0),"ABSENT","PASSED","",400);result(d,results.get(0),"PRESENT","NOT_SELECTED","",400);staff=result(d,results.get(0),"PRESENT","PASSED","Assessment passed",200);result(d,results.get(0),"PRESENT","PASSED","",409);results=staff.get("participants").get(0).get("results");staff=result(d,results.get(1),"PRESENT","PASSED","Interview passed",200);results=staff.get("participants").get(0).get("results");result(d,results.get(0),"PRESENT","NOT_SELECTED","Changed result",409);assertEquals("ROUNDS_COMPLETED",staff.get("participants").get(0).get("progress").asText());long app=staff.get("participants").get(0).get("applicationId").asLong();assertEquals(Model.Stage.APPLIED,r.applications().findById(app).orElseThrow().status);var complete=status(detail(d,jwt("placement@careerbridge.dev")),"COMPLETED",200);result(complete,results.get(1),"PRESENT","PASSED","",409);assertTrue(detail(d,fixture().token(a)).toString().contains("Interview passed"));}
    @Test void cancellationRejectedApplicationsAndPrivateExportsAreHandled()throws Exception{var a=fixture().student();var d=published(job(),false);var joined=register(a,d,200);long app=joined.get("registration").get("applicationId").asLong();call("PATCH","/recruiter/applications/"+app,jwt("recruiter@careerbridge.dev"),Map.of("status","REJECTED"),200);assertEquals("APPLICATION_REJECTED",detail(d,fixture().token(a)).get("registration").get("progress").asText());began(d);var result=detail(d,jwt("placement@careerbridge.dev")).get("participants").get(0).get("results").get(0);result(d,result,"PRESENT","PASSED","",409);a.name="=HYPERLINK(\"bad\")";r.accounts().save(a);String csv=fixture().call("GET","/drives/"+d.get("id").asLong()+"/export",jwt("recruiter@careerbridge.dev"),null).body();assertTrue(csv.contains(a.email));assertTrue(csv.contains("'=HYPERLINK"));call("GET","/drives/"+d.get("id").asLong()+"/export",fixture().token(a),null,403);call("GET","/drives/"+d.get("id").asLong()+"/export",jwt("other-recruiter@careerbridge.dev"),null,403);var cancelled=status(detail(d,jwt("placement@careerbridge.dev")),"CANCELLED",200);register(fixture().student(),cancelled,400);assertEquals(Model.Stage.REJECTED,r.applications().findById(app).orElseThrow().status);assertEquals(1,detail(cancelled,jwt("placement@careerbridge.dev")).get("participants").size());}
    @Test void concurrentDirectApplyAndDriveRegistrationReuseOneApplication()throws Exception{var a=fixture().student();Long job=job();var d=published(job,false);var pool=Executors.newFixedThreadPool(2);try{var latch=new CountDownLatch(1);var one=pool.submit(()->{latch.await();return fixture().call("POST","/student/applications",fixture().token(a),Map.of("jobId",job)).statusCode();});var two=pool.submit(()->{latch.await();return fixture().call("POST","/student/drives/"+d.get("id").asLong()+"/registration",fixture().token(a),null).statusCode();});latch.countDown();assertTrue(Set.of(201,409).contains(one.get()));assertEquals(200,two.get());assertEquals(1,r.applications().findByStudentIdOrderByCreatedAtDesc(a.id).size());assertTrue(r.driveRegistrations().findByDriveIdAndStudentId(d.get("id").asLong(),a.id).isPresent());}finally{pool.shutdownNow();}}
    @Test void adminProvisioningCreatesScopedOfficerAndPublicRegistrationCannotDoSo()throws Exception{String email=UUID.randomUUID()+"@example.com";var body=Map.of("name","Campus Officer","email",email,"password","Staff@12345","role","PLACEMENT_OFFICER","universityId",campus()+1);var officer=call("POST","/admin/users",jwt("admin@careerbridge.dev"),body,201);assertEquals("PLACEMENT_OFFICER",officer.get("role").asText());assertEquals(campus()+1,officer.get("universityId").asLong());var session=call("POST","/auth/login",null,Map.of("email",email,"password","Staff@12345"),200);assertEquals(0,call("GET","/placement/academic-reviews",session.get("token").asText(),null,200).size());call("POST","/auth/register",null,body,403);call("POST","/admin/users",jwt("placement@careerbridge.dev"),body,403);var noCampus=new LinkedHashMap<String,Object>(body);noCampus.remove("universityId");noCampus.put("email",UUID.randomUUID()+"@example.com");call("POST","/admin/users",jwt("admin@careerbridge.dev"),noCampus,400);}
}
